let data;try{data=JSON.parse(localStorage.getItem(KEY));if(!data||data.version!==2)throw Error('invalid')}catch{let old;try{old=JSON.parse(localStorage.getItem(OLD))}catch{}data=old?.routines?migrate(old):defaults();}data.routines||=[];data.runs||=[];data.tasks||=[];data.history||=[];data.v4 ||= {trash:[], templates:[], goals:[], sessions:[], widgets:['quick','routines','active','overview','recurring'],accent:'violet',recurrences:{}};for(const k of ['trash','templates','goals','sessions'])data.v4[k] ||= [];data.v4.widgets ||= ['quick','routines','active','overview','recurring']; let view='dashboard',filter='all',query='',priorityFilter='all',calendarMode='month',calendarDate=new Date(),activeRoutineId=null,toastTimer,drag=null;
function save(){data.v4 ||= {trash:[],templates:[],goals:[],sessions:[],widgets:['quick','routines','active','overview','recurring'],accent:'violet',recurrences:{}};try{localStorage.setItem(KEY,JSON.stringify(data));$('storageStatus').textContent='Saved on this device'}catch{$('storageStatus').textContent='Storage full — export backup';toast('Could not save. Export a backup.')}}function log(type,detail){data.history.unshift({id:uid(),type,detail,time:now()});data.history=data.history.slice(0,1000)}function toast(msg){const el=$('toast');el.textContent=msg;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3200)}function cloneTask(t){return {...task(t.text,t.priority),subtasks:(t.subtasks||[]).map(s=>({id:uid(),text:s.text,done:false}))}}function activeRun(){return data.runs.find(r=>r.id===data.activeRun)}function launch(r){const run={id:uid(),routineId:r.id,name:r.name,emoji:r.emoji,created:now(),tasks:r.template.map(cloneTask)};data.runs.unshift(run);data.activeRun=run.id;log('launched',r.name);save();view='dashboard';render();toast('Started a new independent run')}
function suggested(cmd){const s=cmd.toLowerCase();if(/trip|travel|flight|airport/.test(s))return ['Confirm reservations','Check travel documents','Pack essentials and chargers','Plan transportation','Review itinerary'];if(/meeting|interview|presentation/.test(s))return ['Confirm meeting details','Review agenda','Prepare talking points','Gather materials','Prepare questions','Record follow-up actions'];if(/clean|house|tidy/.test(s))return ['Gather supplies','Clear clutter','Clean surfaces','Vacuum or sweep','Take out trash'];if(/study|exam|class/.test(s))return ['Gather study materials','Review notes','Practice questions','Review mistakes','Plan next session'];return ['Define the outcome','Gather what you need','Complete the first step','Review remaining actions','Confirm completion']}
function runCommand(raw){const s=raw.trim();if(!s)return; if(handleNaturalCommand(s))return;const norm=s.toLowerCase().replace(/[!?.,]/g,'').trim();const r=data.routines.find(r=>r.name.toLowerCase()===norm||(r.aliases||[]).some(a=>a.toLowerCase()===norm))||data.routines.find(r=>r.name.toLowerCase().includes(norm)||(r.aliases||[]).some(a=>a.length>3&&norm.includes(a.toLowerCase())));if(r)return launch(r);const name=s[0].toUpperCase()+s.slice(1),newR=routine(name,'✨',[s],suggested(s).map(t=>[t]));data.routines.push(newR);log('suggested',name);launch(newR);toast('Suggested a checklist — edit its template anytime')}
