function taskRow(t,context){const overdue=t.due&&!t.done&&t.due<today();return `<div class="taskrow" data-row="${escape(t.id)}" draggable="true"><input class="taskcheck" type="checkbox" data-check="${escape(t.id)}" data-context="${context}" ${t.done?'checked':''} aria-label="Complete ${escape(t.text)}"><div class="taskbody"><div class="taskname ${t.done?'completed':''}" data-inline="${escape(t.id)}" data-context="${context}" title="Click to edit">${escape(t.text)}</div><div class="taskmeta"><span class="${t.priority==='high'?'priority-high':t.priority==='low'?'priority-low':''}">${escape(t.priority)} priority</span>${t.due?`<span class="${overdue?'overdue':''}">${overdue?'Overdue · ':''}${formatDate(t.due)}${t.time?' · '+escape(t.time):''}</span>`:''}${t.repeat!=='none'?`<span>↻ ${escape(t.repeat)}</span>`:''}</div>${t.subtasks?.length?`<div class="subtasks">${t.subtasks.map(s=>`<label class="subtask"><input type="checkbox" data-sub="${escape(s.id)}" data-task="${escape(t.id)}" data-context="${context}" ${s.done?'checked':''}><span>${escape(s.text)}</span></label>`).join('')}</div>`:''}</div><div class="rowactions"><button class="iconbtn" data-move="up" data-id="${escape(t.id)}" data-context="${context}" aria-label="Move task up">↑</button><button class="iconbtn" data-move="down" data-id="${escape(t.id)}" data-context="${context}" aria-label="Move task down">↓</button><button class="iconbtn" data-edit="${escape(t.id)}" data-context="${context}" aria-label="Edit task">✎</button><button class="iconbtn" data-delete="${escape(t.id)}" data-context="${context}" aria-label="Delete task">×</button></div></div>`}
