function renderDashboard(){const r=activeRun();return `<div class="panel"><div class="eyebrow">QUICK COMMAND</div><h2 style="margin-top:6px">What are we doing today?</h2><p class="muted small">Launch a saved routine, type a command, or use your voice.</p><form id="commandForm" class="commandbar"><input class="input" id="commandInput" placeholder="Try ‘going to work’ or ‘prepare for a trip’" aria-label="Command"><button type="button" class="btn" id="voice">🎙 Voice</button><button class="btn primary" type="submit">Run command</button></form><div class="small muted" id="voiceHint" style="margin-top:10px">Voice recognition depends on browser support.</div></div><section class="section"><div class="row between"><h2>Quick launch</h2><button class="btn" data-create-routine>+ New routine</button></div><div class="grid">${data.routines.map(r=>`<button class="panel routine-card" data-launch="${escape(r.id)}"><span class="emoji">${escape(r.emoji)}</span><span><strong>${escape(r.name)}</strong><div class="small muted">${r.template.length} template tasks · New run each launch</div></span></button>`).join('')}</div></section><div class="cols"><section class="panel"><div class="row between"><div><div class="eyebrow">ACTIVE ROUTINE RUN</div><h2 style="margin-top:5px">${r?escape(r.emoji+' '+r.name):'No active run'}</h2></div>${r?`<div class="row"><button class="btn small" data-edit-routine="${escape(r.routineId)}">Edit template</button><button class="btn small" data-launch="${escape(r.routineId)}">New run</button></div>`:''}</div>${r?`${progress(r.tasks)}<div class="row" style="margin:15px 0"><button class="btn small ${filter==='all'?'active':''}" data-filter="all">All</button><button class="btn small ${filter==='open'?'active':''}" data-filter="open">Open</button><button class="btn small ${filter==='done'?'active':''}" data-filter="done">Completed</button></div>${filteredTasks(r.tasks).map(t=>taskRow(t,'run')).join('')||'<p class="empty">No tasks match this view.</p>'}<form id="addRunTask" class="commandbar"><input class="input" id="runTaskText" placeholder="Add a task to this run" required><button class="btn primary">Add task</button></form>`:'<p class="empty">Launch a routine to create your first independent checklist.</p>'}</section><aside class="stack"><section class="panel"><h2>Overview</h2><div class="row"><div class="stat"><strong>${data.tasks.filter(t=>!t.done).length}</strong><span class="small muted">Open individual tasks</span></div><div class="stat"><strong>${data.runs.length}</strong><span class="small muted">Routine runs</span></div></div><p class="small muted">Calendar displays individual tasks only.</p></section><section class="panel"><div class="row between"><h2>Recent runs</h2><button class="btn small" data-view="routines">View all</button></div>${data.runs.slice(0,5).map(x=>`<button class="btn" style="width:100%;text-align:left;margin:5px 0;white-space:normal" data-open-run="${escape(x.id)}">${escape(x.emoji+' '+x.name)} · ${x.tasks.filter(t=>t.done).length}/${x.tasks.length}<div class="small muted">${new Date(x.created).toLocaleString()}</div></button>`).join('')||'<p class="empty">No runs yet.</p>'}</section></aside></div>`}
function renderTasks(){return `<section class="panel"><div class="row between"><div><h2>Individual tasks</h2><p class="small muted">Only these tasks appear on your calendar. Routine tasks stay inside their runs.</p></div><div class="row"><button class="btn" id="smartAddTask">✦ Smart Add</button><button class="btn primary" data-new-task>+ Add task</button></div></div><div class="filterrow"><input class="input" id="searchTasks" placeholder="Search tasks..." value="${escape(query)}"><select id="statusFilter"><option value="all" ${filter==='all'?'selected':''}>All statuses</option><option value="open" ${filter==='open'?'selected':''}>Open</option><option value="done" ${filter==='done'?'selected':''}>Completed</option></select><select id="priorityFilter"><option value="all" ${priorityFilter==='all'?'selected':''}>All priorities</option><option value="high" ${priorityFilter==='high'?'selected':''}>High</option><option value="normal" ${priorityFilter==='normal'?'selected':''}>Normal</option><option value="low" ${priorityFilter==='low'?'selected':''}>Low</option></select></div><p class="small muted">Drag to reorder on desktop, or use ↑ and ↓ on mobile. Click a task title to rename it.</p>${filteredTasks(data.tasks).map(t=>taskRow(t,'individual')).join('')||'<p class="empty">No tasks match your filters. Add a task to begin.</p>'}</section>`}
function renderRoutines(){return `<div class="row between"><p class="muted">Every launch creates an independent checklist and preserves earlier runs.</p><button class="btn primary" data-create-routine>+ New routine</button></div><div class="grid">${data.routines.map(r=>`<div class="panel"><div class="row between"><h2>${escape(r.emoji+' '+r.name)}</h2><button class="btn small" data-edit-routine="${escape(r.id)}">Edit</button></div><p class="small muted">${r.template.length} template tasks</p><button class="btn primary" data-launch="${escape(r.id)}">Start new run</button></div>`).join('')}</div><section class="section panel"><h2>Run history</h2>${data.runs.map(r=>`<div class="historyitem row between"><div><strong>${escape(r.emoji+' '+r.name)}</strong><div class="small muted">${new Date(r.created).toLocaleString()} · ${r.tasks.filter(t=>t.done).length}/${r.tasks.length} complete</div></div><div class="row"><button class="btn small" data-open-run="${escape(r.id)}">Open</button><button class="btn small danger" data-delete-run="${escape(r.id)}">Delete</button></div></div>`).join('')||'<p class="empty">No routine runs yet.</p>'}</section>`}
function shiftMonth(n){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+n,1)}function renderCalendar(){const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),start=new Date(year,month,1),first=new Date(start);first.setDate(1-first.getDay());let dates;if(calendarMode==='month'){dates=Array.from({length:42},(_,i)=>{const d=new Date(first);d.setDate(first.getDate()+i);return d})}else{const d=new Date(calendarDate);d.setDate(d.getDate()-d.getDay());dates=Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return x})}return `<section class="panel"><div class="row between"><div><h2>${calendarDate.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><p class="small muted">Individual task deadlines only — routines are excluded.</p></div><div class="row"><button class="btn small" data-cal-prev>←</button><button class="btn small" data-cal-today>Today</button><button class="btn small" data-cal-next>→</button><button class="btn small ${calendarMode==='month'?'active':''}" data-cal-mode="month">Month</button><button class="btn small ${calendarMode==='week'?'active':''}" data-cal-mode="week">Week</button></div></div><div class="calhead ${calendarMode==='week'?'weekmode':''}">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(n=>`<div class="caldayname">${n}</div>`).join('')}${dates.map(d=>{const date=localDate(d),items=data.tasks.filter(t=>occursOn(t,date));return `<div class="calday ${d.getMonth()!==month?'outside':''} ${date===today()?'today':''}"><span class="daynum">${d.getDate()}</span>${items.map(t=>`<button class="calitem ${t.done?'done':''}" data-edit="${escape(t.id)}" data-context="individual">${t.due!==date?'↻ ':''}${escape(t.text)}${t.time?' · '+escape(t.time):''}</button>`).join('')}</div>`}).join('')}</div></section>`}
function renderHistory(){return `<section class="panel"><div class="row between"><h2>Activity history</h2><button class="btn danger" id="clearHistory">Clear history</button></div>${data.history.map(h=>`<div class="historyitem"><strong>${escape(h.type)}</strong> · ${escape(h.detail)}<div><small>${new Date(h.time).toLocaleString()}</small></div></div>`).join('')||'<p class="empty">No activity yet.</p>'}</section>`}
function renderSettings(){return `<section class="panel"><h2>Preferences and backups</h2><div class="settingsrow"><div><strong>Appearance</strong><div class="small muted">Switch between accessible dark and light modes.</div></div><button class="btn" id="settingsTheme">Switch to ${data.theme==='dark'?'light':'dark'}</button></div><div class="divider"></div><div class="settingsrow"><div><strong>Export backup</strong><div class="small muted">Save routines, individual tasks, runs and history as JSON.</div></div><button class="btn" id="export">Export JSON</button></div><div class="settingsrow"><div><strong>Import backup</strong><div class="small muted">Import v1 or v2 backups. Replaces current local data.</div></div><button class="btn" id="importBtn">Import JSON</button></div><div class="divider"></div><p class="hint">Data is stored on this device in your browser. It does not automatically sync between iPhone and computer. Export a backup before clearing browser data or updating from v1.</p><p class="small muted">Reminders are shown while this app is open. Closed-app push notifications are not included.</p></section>`}
function render(){document.documentElement.dataset.accent=data.v4?.accent||'violet';document.documentElement.dataset.theme=data.theme;$('themeToggle').textContent=data.theme==='dark'?'☀ Light':'☾ Dark';const titles={dashboard:'Dashboard',tasks:'My Tasks',routines:'Routines',calendar:'Calendar',history:'History',productivity:'Productivity',tools:'Tools',settings:'Settings'};$('pageTitle').textContent=titles[view];$('sectionLabel').textContent='YOUR WORKSPACE';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('content').innerHTML=({dashboard:renderDashboard,tasks:renderTasks,routines:renderRoutines,calendar:renderCalendar,history:renderHistory,productivity:renderProductivity,tools:renderTools,settings:renderSettings})[view]();bindDynamic();if(view==='dashboard')organizeDashboard()}
function occursOn(t,date){if(!t.due||date<t.due)return false;if(date===t.due)return true;if(t.done)return false;const a=new Date(t.due+'T12:00:00'),b=new Date(date+'T12:00:00'),days=Math.round((b-a)/86400000);if(days<0)return false;switch(t.repeat){case 'daily':return true;case 'weekly':return days%7===0;case 'weekdays':return b.getDay()>=1&&b.getDay()<=5;case 'monthly':return b.getDate()===a.getDate();case 'after':return days%Math.max(1,Number(t.repeatDays)||1)===0;default:return false}}
function upcomingRecurring(){const out=[];for(let n=0;n<30;n++){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+n);const day=localDate(d);for(const t of data.tasks){if(t.repeat&&t.repeat!=='none'&&occursOn(t,day))out.push({t,day})}if(out.length>=12)break}return out.slice(0,8)}
function recurringWidget(){const rows=upcomingRecurring();return `<section class="panel" data-widget-section="recurring"><div class="row between"><h2>Upcoming recurring tasks</h2><button class="btn small" data-view="calendar">Calendar</button></div>${rows.length?rows.map(x=>`<div class="historyitem row between"><span>${escape(x.t.text)}</span><span class="small muted">${escape(formatDate(x.day))}</span></div>`).join(''):'<p class="empty">No recurring tasks in the next 30 days.</p>'}</section>`}
function organizeDashboard(){if(view!=='dashboard')return;const root=$('content'),panels=[...root.children],quick=panels.find(x=>x.classList.contains('panel')),launch=panels.find(x=>x.classList.contains('section')),cols=panels.find(x=>x.classList.contains('cols'));if(!quick||!launch||!cols)return;const active=cols.querySelector(':scope > .panel'),aside=cols.querySelector(':scope > aside'),overview=aside?.querySelector('.panel'),recent=aside?.querySelectorAll('.panel')[1];const sections={quick, routines:launch,active,overview,recurring:null};if(recent){recent.classList.add('dashboard-recent')}const holder=document.createElement('div');holder.className='dashboard-widgets';for(const key of [...new Set([...(data.v4.widgets||[]),'recurring'])]){if((data.v4.hidden||[]).includes(key))continue;let el=key==='recurring'?null:sections[key];if(key==='recurring'){holder.insertAdjacentHTML('beforeend',recurringWidget());continue}if(el){el.dataset.widgetSection=key;holder.append(el)}}root.replaceChildren(holder);if(recent){const extra=document.createElement('div');extra.className='section';extra.append(recent);root.append(extra)}}
function getTask(id,context){return (context==='run'?activeRun()?.tasks:context==='template'?data.routines.find(r=>r.id===activeRoutineId)?.template:data.tasks)?.find(t=>t.id===id)}function getList(context){return context==='run'?activeRun()?.tasks:context==='template'?data.routines.find(r=>r.id===activeRoutineId)?.template:data.tasks}
function complete(t,checked,context){if(checked&&context==='individual'&&t.dependsOn&&data.tasks.some(x=>x.id===t.dependsOn&&!x.done)){toast('Complete the prerequisite task first');render();return}t.done=checked;t.completed=checked?now():null;if(checked&&context==='individual'&&t.repeat!=='none'&&t.due){const d=new Date(t.due+'T12:00:00');if(t.repeat==='daily')d.setDate(d.getDate()+1);if(t.repeat==='weekly')d.setDate(d.getDate()+7);if(t.repeat==='weekdays'){do{d.setDate(d.getDate()+1)}while([0,6].includes(d.getDay()))}if(t.repeat==='after'){d.setDate(d.getDate()+Math.max(1,Number(t.repeatDays)||1))}if(t.repeat==='monthly'){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last))}const next={...task(t.text,t.priority),due:localDate(d),time:t.time,repeat:t.repeat,reminder:t.reminder,repeatDays:t.repeatDays,subtasks:t.subtasks.map(s=>({...s,id:uid(),done:false}))};data.tasks.push(next)}if(checked){data.v4.events ||= [];data.v4.events.push({id:uid(),taskId:t.id,kind:context==='individual'?'task':'routine-task',name:t.text,time:now(),due:t.due||''})}log(checked?'completed':'reopened',t.text);save();render()}
function openTaskEditor(t=null,context='individual'){const d=$('editor');$('editorTitle').textContent=t?'Edit task':'New individual task';$('editId').value=t?.id||'';$('editContext').value=context;$('editName').value=t?.text||'';$('editPriority').value=t?.priority||'normal';$('editDue').value=t?.due||'';$('editTime').value=t?.time||'';$('editRepeat').value=t?.repeat||'none';$('editRepeatDays').value=t?.repeatDays||1;$('editDepends').replaceChildren(new Option('No prerequisite',''),...data.tasks.filter(x=>x.id!==t?.id).map(x=>new Option(x.text,x.id)));$('editDepends').value=t?.dependsOn||'';$('editReminder').value=t?.reminder||'none';$('editSubtasks').value=(t?.subtasks||[]).map(s=>s.text).join('\n');const isIndividual=context==='individual';['editDue','editTime','editRepeat','editReminder'].forEach(id=>$(id).disabled=!isIndividual);d.showModal();$('editName').focus()}
