c.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return}if(b.hasAttribute('data-new-task')){openTaskEditor();return}if(b.hasAttribute('data-create-routine')){openRoutineEditor();return}if(b.dataset.launch){const r=data.routines.find(x=>x.id===b.dataset.launch);if(r)launch(r);return}if(b.dataset.openRun){data.activeRun=b.dataset.openRun;view='dashboard';save();render();return}if(b.dataset.editRoutine){const r=data.routines.find(x=>x.id===b.dataset.editRoutine);if(r)openRoutineEditor(r);return}if(b.dataset.edit){const t=getTask(b.dataset.edit,b.dataset.context);if(t)openTaskEditor(t,b.dataset.context);return}if(b.dataset.delete){const list=getList(b.dataset.context),t=getTask(b.dataset.delete,b.dataset.context);if(t&&confirm(`Move “${t.text}” to Trash?`)){trashItem('task',t,b.dataset.context);list.splice(list.indexOf(t),1);log('deleted',t.text);save();render()}return}if(b.dataset.move){const list=getList(b.dataset.context),i=list.findIndex(t=>t.id===b.dataset.id),j=i+(b.dataset.move==='up'?-1:1);if(i>=0&&j>=0&&j<list.length){[list[i],list[j]]=[list[j],list[i]];save();render()}return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.hasAttribute('data-cal-prev')){calendarMode==='month'?shiftMonth(-1):calendarDate.setDate(calendarDate.getDate()-7);render();return}if(b.hasAttribute('data-cal-next')){calendarMode==='month'?shiftMonth(1):calendarDate.setDate(calendarDate.getDate()+7);render();return}if(b.hasAttribute('data-cal-today')){calendarDate=new Date();render();return}if(b.dataset.calMode){calendarMode=b.dataset.calMode;render();return}if(b.dataset.deleteRun){const r=data.runs.find(x=>x.id===b.dataset.deleteRun);if(r&&confirm(`Move run “${r.name}” to Trash?`)){trashItem('run',r);data.runs=data.runs.filter(x=>x.id!==r.id);if(data.activeRun===r.id)data.activeRun=data.runs[0]?.id||null;log('deleted run',r.name);save();render()}}};
