$('editorForm').onsubmit=e=>{e.preventDefault();const id=$('editId').value,context=$('editContext').value,existing=id?getTask(id,context):null,name=$('editName').value.trim();if(!name)return;const subs=$('editSubtasks').value.split('\n').map(s=>s.trim()).filter(Boolean);const t=existing||task(name);t.text=name;t.priority=$('editPriority').value;t.subtasks=subs.map((s,i)=>{const prev=(existing?.subtasks||[])[i];return prev?.text===s?prev:{id:uid(),text:s,done:false}});if(context==='individual'){t.due=$('editDue').value;t.time=$('editTime').value;t.repeat=$('editRepeat').value;t.repeatDays=Number($('editRepeatDays').value)||1;t.dependsOn=$('editDepends').value||'';t.reminder=$('editReminder').value}if(!existing)data.tasks.push(t);log(existing?'edited':'added',name);save();$('editor').close();render();toast('Task saved')};$('cancelEdit').onclick=()=>$('editor').close();$('cancelRoutine').onclick=()=>$('routineEditor').close();$('routineForm').onsubmit=e=>{e.preventDefault();const id=$('routineId').value,old=data.routines.find(r=>r.id===id),name=$('routineName').value.trim();if(!name)return;const lines=$('routineTasks').value.split('\n').map(s=>s.trim()).filter(Boolean);const template=lines.map(s=>task(s.replace(/^[!~]\s*/,''),s.startsWith('!')?'high':s.startsWith('~')?'low':'normal'));const r={id:old?.id||uid(),name,emoji:$('routineEmoji').value.trim()||'📋',aliases:$('routineAliases').value.split(',').map(s=>s.trim()).filter(Boolean),template};if(old)data.routines[data.routines.indexOf(old)]=r;else data.routines.push(r);log(old?'edited routine':'created routine',name);save();$('routineEditor').close();render();toast('Routine template saved')};$('deleteRoutine').onclick=()=>{const r=data.routines.find(x=>x.id===$('routineId').value);if(r&&confirm(`Move template “${r.name}” to Trash? Previous runs remain.`)){trashItem('routine',r);data.routines=data.routines.filter(x=>x.id!==r.id);log('deleted routine',r.name);save();$('routineEditor').close();render()}};
function exportBackup(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`command-center-${(readProfiles().find(p=>p.id===(localStorage.getItem(ACTIVE_PROFILE)||'default'))?.name||'profile').replace(/[^a-z0-9_-]/gi,'-')}-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('importFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const raw=JSON.parse(await f.text());if(!Array.isArray(raw.routines))throw Error('Not a Command Center backup');const d=raw.version===2?raw:migrate(raw);if(!Array.isArray(d.tasks)||!Array.isArray(d.runs)||!Array.isArray(d.history))throw Error('Invalid backup structure');if(!confirm('Replace all data stored on this device with this backup?'))return;data=d;data.v4 ||= {trash:[],templates:[],goals:[],sessions:[],widgets:['quick','routines','active','overview','recurring'],accent:'violet',recurrences:{}};save();render();toast('Backup imported')}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}};
let lastReminder=new Set();function checkReminders(){const current=new Date();for(const t of data.tasks){if(t.done||!t.due||!t.time||t.reminder==='none')continue;const due=new Date(t.due+'T'+t.time+':00');const mins=t.reminder==='at'?0:Number(t.reminder),alertAt=new Date(due.getTime()-mins*60000);const key=t.id+'-'+t.due+'-'+t.time;if(current>=alertAt&&current.getTime()-alertAt.getTime()<60000&&!lastReminder.has(key)){lastReminder.add(key);toast('Reminder: '+t.text)}}}setInterval(checkReminders,30000);
