function handleNaturalCommand(input){const s=input.trim();const m=s.match(/^(?:remind me to|add task|create task|todo|to do)\s+(.+)$/i);if(!m)return false;let title=m[1],due='',time='';const dateMatch=title.match(/\b(today|tomorrow|next monday|next tuesday|next wednesday|next thursday|next friday|next saturday|next sunday)\b/i);if(dateMatch){const d=new Date();const word=dateMatch[1].toLowerCase();if(word==='tomorrow')d.setDate(d.getDate()+1);else if(word.startsWith('next ')){const weekdays=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];let delta=(weekdays.indexOf(word.slice(5))-d.getDay()+7)%7;if(!delta)delta=7;d.setDate(d.getDate()+delta)}due=localDate(d);title=title.replace(dateMatch[0],'')};const tm=title.match(/\b(?:at\s+)?(\d{1,2})(?::(\d\d))?\s*(am|pm)\b/i);if(tm){let h=Number(tm[1])%12;if(tm[3].toLowerCase()==='pm')h+=12;time=String(h).padStart(2,'0')+':'+(tm[2]||'00');title=title.replace(tm[0],'')}title=title.replace(/\s+/g,' ').trim().replace(/\s+(on|at)$/i,'');if(!title){toast('Please include a task name');return true}const t=task(title);t.due=due;t.time=time;t.reminder=due&&time?'at':'none';data.tasks.push(t);log('added via command',title);save();view='tasks';render();toast('Created: '+title);return true}
