function setupSmartDialog(){const d=document.createElement('dialog');d.id='smartDialog';d.className='smart-dialog';d.innerHTML=`<form id="smartForm"><div class="row between"><h2>✦ Smart Add Task</h2><button type="button" class="btn" id="smartClose">Close</button></div><p class="muted">Write a task naturally. Dates and times are recognized locally. Review the preview before saving.</p><label for="smartText">What do you need to do?</label><textarea id="smartText" class="input" rows="3" placeholder="Remind me to submit my report tomorrow at 3 PM" required></textarea><p class="small muted">Try an example:</p><div class="row smart-examples"><button type="button" class="btn small" data-example="Remind me to submit my report tomorrow at 3 PM">Report tomorrow</button><button type="button" class="btn small" data-example="Add task call the dentist next Monday at 10 AM">Dentist next Monday</button><button type="button" class="btn small" data-example="Create task pay electricity bill today">Bill today</button></div><div class="panel" id="smartPreview" aria-live="polite">Type a command to preview the task.</div><div class="actions"><button type="button" class="btn" id="smartCancel">Cancel</button><button type="submit" class="btn primary">Create task</button></div></form>`;document.body.append(d);const close=()=>d.close();$('smartClose').onclick=close;$('smartCancel').onclick=close;d.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('smartText').value=b.dataset.example;preview()});const preview=()=>{const raw=$('smartText').value.trim();const m=raw.match(/^(?:remind me to|add task|create task|todo|to do)\s+(.+)$/i);let text=m?m[1]:raw;const date=text.match(/\b(today|tomorrow|next monday|next tuesday|next wednesday|next thursday|next friday|next saturday|next sunday)\b/i);const time=text.match(/\b(?:at\s+)?(\d{1,2})(?::(\d\d))?\s*(am|pm)\b/i);$('smartPreview').innerHTML='<strong>Task preview</strong><div>'+escape(text.replace(date?.[0]||/\b^$/,'').replace(time?.[0]||/\b^$/,'').trim())+'</div><div class="small muted">Date: '+escape(date?.[0]||'Not specified')+' · Time: '+escape(time?.[0]||'Not specified')+'</div>'};$('smartText').oninput=preview;$('smartForm').onsubmit=e=>{e.preventDefault();let raw=$('smartText').value.trim();if(!raw)return;const valid=/^(?:remind me to|add task|create task|todo|to do)\s+/i.test(raw);if(!valid)raw='Add task '+raw;close();handleNaturalCommand(raw)}}

